checkRuns.command:
cat > src/routes/contact.kay <<'EOF'
--- server
import { t } from 'kay'
import { checkContact } from '../contact'
import ContactForm from '../components/contact-form.kay'

const contactMessage = t.Object({
  name: t.Optional(t.String({ maxLength: 200 })),
  email: t.Optional(t.String({ maxLength: 320 })),
  message: t.Optional(t.String({ maxLength: 10000 })),
})

export const contact = action(contactMessage, (input, ctx) => {
  const fields = { name: input.name ?? '', email: input.email ?? '', message: input.message ?? '' }
  const errors = checkContact(fields)

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return { name: fields.name.trim() }
})
---
head
  title Contact
h1 Contact
ContactForm
EOF
cat > src/components/contact-form.kay <<'EOF'
---
import { contact } from '../routes/contact.kay'
import { checkContact } from '../contact'
import type { ContactErrors } from '../contact'

const refused = contact.failed()
const errors = signal<ContactErrors>({ ...refused?.errors, ...refused?.data?.errors })
const thanked = signal(contact.succeeded()?.data.name ?? '')

async function submit(event: SubmitEvent) {
  event.preventDefault()
  const form = event.currentTarget as HTMLFormElement
  const fields = new FormData(form)
  const found = checkContact({
    name: String(fields.get('name') ?? ''),
    email: String(fields.get('email') ?? ''),
    message: String(fields.get('message') ?? ''),
  })

  errors.set(found)
  thanked.set('')

  if (Object.keys(found).length > 0)
    return

  try {
    thanked.set((await contact(fields, { refresh: false })).name)
    form.reset()
  }
  catch (error) {
    if (error instanceof ActionError)
      errors.set({ ...error.errors, ...(error.data as { errors?: ContactErrors } | undefined)?.errors })
    else
      throw error
  }
}
---
if thanked
  p(role="status") Thanks, {thanked}! Your message has been sent.
form(action={contact} novalidate onSubmit={submit})
  div
    label(for="contact-name") Name
    input#contact-name(type="text" name="name")
    if errors.name
      p.error {errors.name}
  div
    label(for="contact-email") Email
    input#contact-email(type="email" name="email")
    if errors.email
      p.error {errors.email}
  div
    label(for="contact-message") Message
    textarea#contact-message(name="message")
    if errors.message
      p.error {errors.message}
  button(type="submit") Send
EOF
bun run check 2>&1 | tail -30
